  "/workspace/local/workspace/run-ceobench/observe.py": {
    "type": "add",
    "content": "import json
import novamind_api as nm

day = nm.vars.current_day
queries = {
    'finance': f"SELECT category,ROUND(SUM(amount),2) AS amount FROM ledger WHERE day>{day-7} GROUP BY category",
    'book': "SELECT c.group_id,s.plan,s.status,COUNT(*) AS n,SUM(s.seat_count) AS seats,ROUND(AVG(s.effective_price),2) AS price,ROUND(SUM(s.effective_price*s.seat_count),2) AS mrr FROM subscriptions s JOIN customers c USING(customer_id) GROUP BY c.group_id,s.plan,s.status",
    'threads': "SELECT t.* ,c.group_id FROM enterprise_turns t JOIN customers c USING(customer_id) WHERE t.message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id) AND t.closed=0 ORDER BY t.customer_id",
    'ads': f"SELECT channel_id,group_id,ROUND(SUM(spend),2) AS spend,SUM(leads_generated) AS leads FROM ad_channel_leads WHERE day>{day-7} GROUP BY channel_id,group_id",
    'service': f"SELECT * FROM service_day WHERE day>{day-7}",
    'ad_income': f"SELECT group_id,ROUND(SUM(revenue),2) AS revenue,COUNT(*) AS customer_days FROM ads_revenue WHERE day>{day-7} GROUP BY group_id",
}
print('DAY',day,flush=True)
for name,sql in queries.items():
    print(name,json.dumps(nm.query(sql)['rows']),flush=True)
"
  }
}

