import json, math
from pathlib import Path
import novamind_api as nm
from novamind_api._client import next_week

root=Path('/workspace/local/workspace/run-ceobench')
policy=json.loads((root/'policy.json').read_text())
day=nm.vars.current_day
if day>=500:
    raise SystemExit('Already at horizon; no advance submitted.')
if day!=policy['day']:
    raise SystemExit(f"Policy day {policy['day']} differs from current day {day}; no actions submitted.")
def q(sql): return nm.query(sql)['rows']
def action(label,fn,*args,**kwargs):
    result=fn(*args,**kwargs)
    print(label,json.dumps(result),flush=True)
    return result

cash=q('SELECT SUM(amount) AS cash FROM ledger')[0]['cash']
book=q("SELECT c.group_id,COUNT(*) AS accounts,SUM(s.seat_count) AS seats,SUM(s.effective_price*s.seat_count) AS mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id")
print('BEFORE',json.dumps({'day':day,'cash':cash,'book':book}),flush=True)
known=q('SELECT group_id,discovered_day FROM group_info_levels WHERE info_level>0')
groups=[r['group_id'] for r in known]
if policy.get('discover',0):
    for _ in range(policy['discover']):
        if len(groups)>=26: break
        result=action('DISCOVERY',nm.market.research_market)
        g=result.get('discovered_group_id')
        if g:
            groups.append(g)
            insight=action('NEW_INSIGHT',nm.market.get_group_insights,g)

if 'prices' in policy: action('PRICES',nm.pricing.set_prices,**dict(zip('ABC',policy['prices'])))
if 'tiers' in policy: action('TIERS',nm.pricing.set_model_tiers,**dict(zip('ABC',policy['tiers'])))
if 'quotas' in policy: action('QUOTAS',nm.pricing.set_usage_quotas,**dict(zip('ABC',policy['quotas'])))
if 'capacity' in policy: action('CAPACITY',nm.infrastructure.set_capacity_tier,policy['capacity'])
if 'ops' in policy: action('SPEND',nm.marketing.set_daily_spend,operations=policy['ops'],development=policy['global_dev'])
if 'dev_default' in policy:
    dev={g:policy.get('dev',{}).get(g,policy['dev_default']) for g in groups}
    action('TARGET_DEV',nm.analytics.set_targeted_dev_spend,dev)
if 'ads' in policy: action('ACQUISITION',nm.marketing.set_targeted_ad_spend,policy['ads'])
if 'ad_strength' in policy: action('AD_MONETIZATION',nm.marketing.set_ads_strength,by_group=policy['ad_strength'])
if 'target_ops' in policy: action('TARGET_OPS',nm.analytics.set_targeted_ops_spend,by_group=policy['target_ops'])
for tier in policy.get('research',[]):
    action('RESEARCH',nm.research.start_research_project,tier)

base={'E1':32,'E2':60,'E3':90,'D_E01':65,'D_E02':35,'D_E03':80,'D_E04':70,'D_E05':85,'D_E06':65,'D_E07':110,'D_E08':95,'D_E09':55,'D_E10':75}
base.update(policy.get('enterprise_prices',{}))
rows=q("SELECT t.customer_id,t.sender,t.thread_type,t.offer_json,c.group_id FROM enterprise_turns t JOIN customers c USING(customer_id) WHERE t.message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id) AND t.closed=0 AND t.sender<>'agent' AND EXISTS (SELECT 1 FROM subscriptions s WHERE s.customer_id=t.customer_id AND s.status IN ('lead','subscribed')) ORDER BY t.message_id")
active={r['customer_id']:r for r in q("SELECT customer_id,effective_price,plan FROM subscriptions WHERE status='subscribed'")}
deals=[]
seen=set()
for r in rows:
    cid=r['customer_id']
    if cid in seen: continue
    seen.add(cid)
    price=base.get(r['group_id'],60)
    offer=json.loads(r['offer_json'] or '{}')
    counter=offer.get('price') if isinstance(offer,dict) else None
    if r['sender']=='customer':
        if r['thread_type'] in ('churn_prevention','renewal','plan_change') and cid in active:
            price=min(price,active[cid]['effective_price']*policy.get('retention_fraction',0.95))
        elif counter is not None:
            price=max(price*0.5,min(price*0.85,float(counter)*1.08))
        else: price*=0.7
    deals.append([cid,[['C',round(max(1,price),2)]]])
if deals:
    result=nm.enterprise.send_enterprise_deal(deals)
    failures=[r for r in result.get('results',[]) if not r.get('success')]
    print('ENTERPRISE',json.dumps({'sent':len(deals),'failures':failures}),flush=True)
    if failures: raise SystemExit('Deal failures require inspection; no week advanced.')

if policy.get('renegotiate'):
    occupied={r['customer_id'] for r in q("SELECT DISTINCT customer_id FROM enterprise_turns WHERE closed=0 AND day>= %d"%(day-14))}
    reneg=[]
    for r in q("SELECT s.customer_id,s.effective_price,c.group_id FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND c.customer_type='large'"):
        desired=base.get(r['group_id'],60)
        if r['customer_id'] not in occupied and r['effective_price']<desired*0.85:
            reneg.append([r['customer_id'],[['C',desired]]])
    if reneg:
        result=nm.enterprise.send_enterprise_deal(reneg)
        print('RENEGOTIATE',json.dumps({'sent':len(reneg),'failures':[r for r in result.get('results',[]) if not r.get('success')]}),flush=True)

cash=q('SELECT SUM(amount) AS cash FROM ledger')[0]['cash']
points=policy['forecasts']
widths=policy.get('uncertainty',[0.22,0.45,0.65,0.75])
pred={k:{'point':v,'lower':max(0,v*(1-w)),'upper':v*(1+w)} for k,v,w in zip(['cash_1wk','cash_4wk','cash_12wk','cash_26wk'],points,widths)}
rationale=policy['rationale']+f' Observed day {day}, cash ${cash:,.0f}; handled {len(deals)} actionable enterprise negotiations. Watching collections, customer retention, capacity and marginal acquisition returns.'
print('ADVANCING',json.dumps({'day':day,'forecasts':pred,'rationale':rationale}),flush=True)
result=next_week(predictions=pred,rationale=rationale,request_id=f'policy-week-{day:03d}')
(root/'strategy_reports').mkdir(exist_ok=True)
(root/'strategy_reports'/f'week-{day:03d}.json').write_text(json.dumps(result,indent=2))
print('WEEK_RESULT',json.dumps(result),flush=True)
