import json,re,math
from pathlib import Path
import novamind_api as nm

ROOT=Path('/workspace/local/workspace/run-ceobench')
def rows(sql): return nm.query(sql)['rows']
def run_block(weeks):
    for iteration in range(weeks):
        day=nm.vars.current_day
        if day>=500: return
        cash=rows('SELECT SUM(amount) AS x FROM ledger')[0]['x']
        if cash<=0: return
        previous=json.loads((ROOT/'strategy_reports'/f'week-{day-7:03d}.json').read_text())
        dash=previous['dashboard']
        quality={m[0]:float(m[1]) for m in re.findall(r'^((?:D_)?[SE]\d+)\s+(\d+\.\d+)',dash,re.M)}
        known=rows('SELECT group_id,info_level FROM group_info_levels WHERE info_level>0')
        cache_path=ROOT/'observed_markets.json'
        cache=json.loads(cache_path.read_text()) if cache_path.exists() else {}
        for g in known:
            if g['group_id'] not in cache or cache[g['group_id']]['info_level']!=g['info_level']:
                cache[g['group_id']]=nm.market.get_group_insights(g['group_id'])
        cache_path.write_text(json.dumps(cache,indent=2))
        groupbook={r['group_id']:r for r in rows("SELECT c.group_id,COUNT(*) AS n,SUM(s.seat_count) AS seats,SUM(s.effective_price*s.seat_count) AS mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id")}
        finance={r['category']:r['x'] for r in rows(f'SELECT category,SUM(amount) AS x FROM ledger WHERE day>{day-7} GROUP BY category')}
        rev=finance.get('subscription_payment',0)+finance.get('ad_revenue',0)
        recurring_cost=-sum(v for k,v in finance.items() if k not in ['subscription_payment','ad_revenue','initial_funding','market_research','group_research','research_project'])
        old_dev=-finance.get('development',0)/7
        predev_surplus=(rev-recurring_cost)/7+old_dev
        dev_budget=max(15000,min(max(old_dev*1.25,predev_surplus*.68),cash/5))
        global_dev=20000 if min(quality.values())<1.8 else (5000 if day<385 else 0)
        proposed={g:(12000 if g in ('E2','E3') and quality[g]<1.1 else 10000 if quality[g]<.9 else 5000 if quality[g]<1.3 else 2000 if quality[g]<1.85 else 0) for g in quality}
        if day>400: proposed={g:(v if quality[g]<1.6 else 0) for g,v in proposed.items()}
        scale=min(1,max(0,(dev_budget-global_dev)/max(1,sum(proposed.values()))))
        dev={g:round(v*scale/100)*100 for g,v in proposed.items()}
        if day>475: global_dev=0;dev={g:0 for g in dev}
        # Match support investment to observed issue arrivals, and clear older backlogs.
        issue=rows(f"SELECT group_id,SUM(CASE WHEN open_day>{day-7} THEN 1 ELSE 0 END) AS arrivals,SUM(CASE WHEN status='open' AND days_open>1 THEN 1 ELSE 0 END) AS old FROM issues GROUP BY group_id")
        target_ops={r['group_id']:round(min(60000,(r['arrivals']/7*1.15+r['old']/3)/(.3 if r['group_id'].startswith(('S','D_S')) else .05))/50)*50 for r in issue}
        ops=2500
        # Keep capacity ahead of measured usage growth.
        usage=rows(f'SELECT MAX(total_usage_units) AS x FROM service_day WHERE day>{day-7}')[0]['x']
        caps=[50000,200000,800000,2500000,8000000,25000000,80000000,300000000]
        cap=next((i for i,v in enumerate(caps) if v>usage*1.55),7)
        qs=quality.get('S3',1)
        prices=[19 if day<140 else 25 if day<210 else 29,69 if qs<1.2 else 89 if qs<1.65 else 109,149 if qs<1.2 else 179 if qs<1.65 else 199 if qs<2.2 else 229]
        premium_tier=1 if min(quality.values())>=1.35 else 2
        # Small monetization tests first; grow only with a quality cushion.
        strengths={g:(1.0 if quality[g]>1.85 else .5 if quality[g]>1.5 else .1 if quality[g]>1.1 else 0) for g in quality}
        base={'E1':36,'E2':60,'E3':90,'D_E01':65,'D_E02':35,'D_E03':80,'D_E04':70,'D_E05':85,'D_E06':65,'D_E07':110,'D_E08':95,'D_E09':55,'D_E10':75}
        for g in base:
            e=cache[g]['estimates']
            delivered=quality[g]*(1.25 if premium_tier==2 else 1)
            fraction=max(.25,min(.85,.35+.30*max(0,delivered-.65)))
            if cache[g]['info_level']>=4:
                base[g]=round(e['willingness_to_pay']*fraction,2)
            else:
                base[g]=round(base[g]*max(.55,min(1.8,.65+.45*delivered)),2)
        # Probe channels in new retail groups, scale successful acquisition, cut poor CAC.
        adrows=rows(f'SELECT group_id,channel_id,SUM(spend) AS spend,SUM(leads_generated) AS leads FROM ad_channel_leads WHERE day>{day-7} GROUP BY group_id,channel_id')
        ad_by={}
        for r in adrows: ad_by.setdefault(r['group_id'],[]).append(r)
        new={r['group_id']:r for r in rows(f"SELECT c.group_id,COUNT(*) AS n,AVG(s.effective_price) AS price FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.created_day>{day-7} AND s.status='subscribed' AND c.acquisition_source IN ('social_media','search_ads','linkedin','content_marketing','referral_program') GROUP BY c.group_id")}
        ads={}
        for g in quality:
            if not g.startswith(('S','D_S')) or quality[g]<.55: continue
            recent=ad_by.get(g,[])
            if not recent:
                for channel in ['social_media','search_ads','linkedin','content_marketing','referral_program']:
                    ads.setdefault(channel,{})[g]=150
                continue
            best=max(recent,key=lambda r:r['leads']/max(1,r['spend']))
            total=sum(r['spend'] for r in recent)
            acquired=new.get(g,{}).get('n',0)
            avgprice=new.get(g,{}).get('price',19)
            cac=total/max(1,acquired)
            current=total/7
            budget=min(25000,current*1.35) if cac<avgprice*.9 else max(150,current*.45)
            if day>440 and cac>avgprice*.6: budget=0
            ads.setdefault(best['channel_id'],{})[g]=round(budget)
        total_ads=sum(sum(v.values()) for v in ads.values())
        ad_cap=max(10000,rev/7*.18)
        if total_ads>ad_cap:
            ads={c:{g:round(v*ad_cap/total_ads) for g,v in a.items()} for c,a in ads.items()}
        # Research is financed from excess cash, with a bounded total quality pipeline.
        research=[]
        rd=nm.research.list_research_projects()['tiers']
        pipeline=rows("SELECT SUM(CASE WHEN status='completed' THEN quality_boost_applied ELSE expected_quality_boost END) AS q FROM research_projects")[0]['q'] or 0
        research_budget=max(0,min(cash*.18,cash-6000000))
        if day<220 and pipeline<2.7:
            for r in reversed(rd):
                if not r['in_progress'] and r['cost']<=research_budget and pipeline<2.7:
                    research.append(r['tier']);research_budget-=r['cost'];pipeline+=r['mean_quality_boost']
        group_research=[]
        if cash>12000000 and day<280:
            budget=min(cash*.08,2100000)
            for g in sorted(base,key=lambda g:groupbook.get(g,{}).get('mrr',0),reverse=True):
                if cache[g]['info_level']<5 and budget>=700000:
                    group_research.append(g);budget-=700000
        weekly_net=rev-recurring_cost
        mrr=sum(r['mrr'] for r in groupbook.values())
        current_week=max(weekly_net,mrr*7/30-recurring_cost)
        points=[]
        oneoffs=sum(next(r['cost'] for r in rd if r['tier']==t) for t in research)+700000*len(group_research)
        for horizon in (7,28,84,182):
            n=min(horizon,500-day)/7
            # Growth tapers as markets fill; uncertainty widens with the horizon.
            growth=.13 if day<180 else .04 if day<300 else .005
            cap_profit=max(3000000,current_week*4,20000000 if day>150 else 8000000)
            future=0
            for w in range(math.ceil(n)):
                step=min(cap_profit,max(50000,current_week)*(1+growth)**w)
                future+=step*min(1,max(0,n-w))
            points.append(round(max(0,cash-oneoffs+future)))
        rationale=f'Adaptive weekly review: retail accounts {sum(r["n"] for g,r in groupbook.items() if g.startswith(("S","D_S")))}, enterprise seats {sum(r["seats"] for g,r in groupbook.items() if not g.startswith(("S","D_S")))}, MRR ${mrr:,.0f}, last operating cash flow ${weekly_net:,.0f}. Allocate development to quality gaps, ops to issue arrivals, and advertising to measured acquisition returns. Scale capacity ahead of measured peak {usage:,.0f}; phase in ad revenue only with quality headroom. Price for quality and individual enterprise counters; retain existing contracts and periodically renegotiate old low rates.'
        policy={'day':day,'prices':prices,'tiers':[1,1,premium_tier],'capacity':cap,'ops':ops,'global_dev':global_dev,'dev_default':0,'dev':dev,'ads':ads,'ad_strength':strengths,'target_ops':target_ops,'enterprise_prices':base,'research':research,'research_groups':group_research,'renegotiate':day%28==0,'forecasts':points,'uncertainty':[.3,.55,.85,1.1],'rationale':rationale}
        (ROOT/'policy.json').write_text(json.dumps(policy,indent=2))
        print('WEEKLY_ANALYSIS',json.dumps({'day':day,'cash':cash,'mrr':mrr,'operating_cash_flow':weekly_net,'quality_range':[min(quality.values()),max(quality.values())],'dev':global_dev+sum(dev.values()),'ads':sum(sum(v.values()) for v in ads.values()),'ops':ops+sum(target_ops.values()),'research':research,'group_research':group_research}),flush=True)
        exec(compile((ROOT/'play_week.py').read_text(),'play_week.py','exec'),{'__name__':'__main__'})

run_block(4)
