    "type": "add",
    "content": "import json,re,math
from pathlib import Path
import novamind_api as nm
ROOT=Path('/workspace/local/workspace/run-ceobench')
def query(sql): return nm.query(sql)['rows']
for step in range(4):
    day=nm.vars.current_day
    if day>=500: break
    cash=query('SELECT SUM(amount) AS x FROM ledger')[0]['x']
    if cash<=0: break
    result=json.loads((ROOT/'strategy_reports'/f'week-{day-7:03}.json').read_text())
    quality={g:float(v) for g,v in re.findall(r'^((?:D_)?[SE]\d+)\s+(\d+\.\d+)',result['dashboard'],re.M)}
    finance={r['category']:r['v'] for r in query(f'SELECT category,SUM(amount) AS v FROM ledger WHERE day>{day-7} GROUP BY category')}
    revenue=finance.get('subscription_payment',0)
    operating=sum(v for k,v in finance.items() if k not in ('market_research','group_research','research_project','initial_funding'))
    book=query("SELECT c.group_id,COUNT(*) AS n,SUM(s.seat_count) AS seats,SUM(s.effective_price*s.seat_count) AS mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id")
    mrr=sum(r['mrr'] for r in book)
    peak=query(f'SELECT MAX(total_usage_units) AS x FROM service_day WHERE day>{day-7}')[0]['x']
    groups=list(quality)
    global_dev=5000 if cash<6000000 else 10000
    dev={g:0 for g in groups}
    for g in ('E1','S3','E2','E3'): dev[g]=5000
    if cash>5000000:
        for g in groups:
            if g not in ('E1','S3','E2','E3'): dev[g]=2000
    if cash<1500000 or operating<0:
        global_dev=0
        dev={g:(5000 if g in ('E1','S3') else 0) for g in groups}
    if day>470: global_dev=0;dev={g:0 for g in groups}
    # Spend directly against the observed support workload.
    workload=query(f"SELECT group_id,SUM(CASE WHEN open_day>{day-7} THEN 1 ELSE 0 END) AS new,SUM(CASE WHEN status='open' AND days_open>1 THEN 1 ELSE 0 END) AS old FROM issues GROUP BY group_id")
    support={r['group_id']:max(50,round((r['new']/7*1.1+r['old']/3)/(.3 if r['group_id'].startswith(('S','D_S')) else .05)/50)*50) for r in workload}
    cap_ops=max(7000,revenue/7*.10)
    if sum(support.values())>cap_ops:
        scale=cap_ops/sum(support.values());support={g:round(v*scale/50)*50 for g,v in support.items()}
    core=min(quality['E1'],quality['S3'])
    tier_b=1 if core>3.2 else 2
    tier_c=1 if core>5.0 and min(quality.values())>3.0 else 2 if core>3.0 and min(quality.values())>1.6 else 3
    prices=[15 if quality['S1']<1.8 else 19,49 if core<2.5 else 69 if core<3.5 else 89,129 if core<2.5 else 149 if core<3.5 else 179]
    capacities=[50000,200000,800000,2500000,8000000,25000000,80000000,300000000]
    capacity=next((i for i,v in enumerate(capacities) if v>peak*1.45),7)
    ads={}
    conversion=query(f"SELECT c.group_id,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) AS won,COUNT(*) AS leads FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.created_day>{day-7} AND c.customer_type='small' GROUP BY c.group_id")
    conversion={r['group_id']:r for r in conversion}
    # Scale only a group with demonstrated conversion and first-month gross margin.
    if operating>300000 and cash>2000000:
        for g,r in conversion.items():
            if r['won']/max(1,r['leads'])>.3:
                ads.setdefault('referral_program',{})[g]=3000 if cash<5000000 else 8000 if cash<20000000 else 15000
    base={'E1':30 if quality['E1']<2.5 else 40 if quality['E1']<3.5 else 48,'E2':65,'E3':90,'D_E01':65,'D_E02':30,'D_E03':70,'D_E04':65,'D_E05':55,'D_E06':40,'D_E07':90,'D_E08':70,'D_E09':45,'D_E10':40}
    if core>3:
        base={g:round(v*1.25,2) for g,v in base.items()}
    research=[]
    tiers=nm.research.list_research_projects()['tiers']
    pipeline=query("SELECT SUM(CASE WHEN status='completed' THEN quality_boost_applied ELSE expected_quality_boost END) AS x FROM research_projects")[0]['x'] or 0
    budget=max(0,min(cash*.25,cash-4000000))
    if day<300 and pipeline<3.5:
        for r in reversed(tiers):
            if r['in_progress']==0 and r['cost']<=budget and pipeline<3.5:
                research.append(r['tier']);budget-=r['cost'];pipeline+=r['mean_quality_boost']
    research_groups=[]
    pending_path=ROOT/'market_research_pending.json'
    pending=json.loads(pending_path.read_text()) if pending_path.exists() else {}
    known=query('SELECT group_id,info_level FROM group_info_levels WHERE info_level>0')
    if cash>12000000:
        for g in ('E2','E3'):
            info=next(r['info_level'] for r in known if r['group_id']==g)
            if info<5 and g not in pending: research_groups.append(g)
    oneoff=sum(next(r['cost'] for r in tiers if r['tier']==t) for t in research)+700000*len(research_groups)
    profit=max(50000,operating)
    if operating<0: profit=max(0,mrr*7/30+sum(v for k,v in finance.items() if v<0 and k not in ('group_research','research_project','market_research')))
    points=[]
    for horizon in (7,28,84,182):
        n=min(horizon,500-day)/7
        amount=0
        for w in range(math.ceil(n)):
            amount+=min(25000000,max(100000,profit)*(1.10 if day<280 else 1.025)**w)*min(1,max(0,n-w))
        points.append(round(max(0,cash-oneoff+amount)))
    policy={'day':day,'prices':prices,'tiers':[1,tier_b,tier_c],'quotas':[250,700,1500],'capacity':capacity,'ops':2000,'global_dev':global_dev,'dev_default':0,'dev':dev,'target_ops':support,'ads':ads,'ad_strength':{g:0 for g in groups},'enterprise_plan':{'E1':'B'},'enterprise_prices':base,'retention_fraction':.95,'renegotiate':day%28==0,'research':research,'research_groups':research_groups,'forecasts':points,'uncertainty':[.4,.65,.9,1.1],'rationale':f'Weekly observed review: cash${cash:,.0f}, MRR${mrr:,.0f}, operating cash flow${operating:,.0f}, peak usage{peak:,.0f}. Maintain generous quotas and no in-app ads; use E1 planB for margin and premium tier{tier_c} for other customers. Limit development to affordable quality improvements, support to actual issue arrivals, and acquisition to groups converting above30%. Fund R&D only from cash above reserve. Negotiate enterprise prices and preserve profitable customer relationships.'}
    if peak>230000000:
        population=sum(r['seats'] for r in book)
        policy['quotas']=[250,700,max(300,int(250000000/max(1,population)))]
        policy['capacity']=7
    (ROOT/'policy.json').write_text(json.dumps(policy,indent=2))
    print('REVIEW',json.dumps({'day':day,'cash':cash,'mrr':mrr,'operating':operating,'dev':global_dev+sum(dev.values()),'ops':2000+sum(support.values()),'ads':ads,'research':research,'conversions':conversion}),flush=True)
    exec(compile((ROOT/'play_week.py').read_text(),'play_week.py','exec'),{'__name__':'__main__'})
"
  }
}

