  "/workspace/local/workspace/run-ceobench/play_week.py": {
    "type": "update",
    "unified_diff": "@@ -17,3 +17,3 @@
 core_cache_path=root/'enterprise_research.json'
-if core_cache_path.exists() and 224<=day<400:
+if core_cache_path.exists() and 224<=day<400 and not policy.get('skip_core_override'):
     core_cash=nm.query('SELECT SUM(amount) AS cash FROM ledger')['rows'][0]['cash']
",
    "move_path": null
  },
  "/workspace/local/workspace/run-ceobench/prepare_recovery.py": {
    "type": "add",
    "content": "import json,math,re
from pathlib import Path
import novamind_api as nm
root=Path('/workspace/local/workspace/run-ceobench')
day=nm.vars.current_day
assert day==245
work=nm.query("SELECT group_id,SUM(CASE WHEN open_day>238 THEN 1 ELSE 0 END) AS arrivals,SUM(CASE WHEN status='open' AND days_open>1 THEN 1 ELSE 0 END) AS aged FROM issues GROUP BY group_id")['rows']
support={r['group_id']:max(100,math.ceil((r['arrivals']/7*1.2+r['aged']/3)/(.3 if r['group_id'].startswith(('S','D_S')) else .05)/100)*100) for r in work}
promotion=json.loads(nm.query("SELECT settings_json FROM config_overrides WHERE tool_name='set_promotion' ORDER BY id DESC LIMIT 1")['rows'][0]['settings_json'])
data=json.loads((root/'enterprise_research.json').read_text())
dash=json.loads((root/'strategy_reports/week-238.json').read_text())['dashboard']
quality={g:float(v) for g,v in re.findall(r'^((?:D_)?[SE]\d+)\s+(\d+\.\d+)',dash,re.M)}
base={}
for g,info in data.items():
    e=info['estimates']
    floor=e['quality_floor_q_min']+max(0,day-info.get('_read_day',day))*.015
    margin=max(0,quality[g]*1.5-floor)
    price=e['willingness_to_pay']*.9*margin/(margin+.4)
    base[g]=round(max(e['usage_volume']*.006*30*1.15+2,price),2)
groups=[r['group_id'] for r in nm.query('SELECT group_id FROM group_info_levels WHERE info_level>0')['rows']]
dev={g:(50000 if g in ('E1','E2','E3') else 5000) for g in groups}
policy={'day':245,'prices':[19,399,179],'tiers':[1,3,2],'quotas':[250,700,1500],'capacity':7,'ops':5000,'global_dev':10000,'dev_default':0,'dev':dev,'skip_core_override':True,'target_ops':support,'ads':{},'ad_strength':{g:0 for g in groups},'promotion':{'by_group_plan':promotion['by_group_plan']},'enterprise_plan':{g:'B' for g in base},'enterprise_prices':base,'retention_fraction':.95,'renegotiate':False,'forecasts':[42000000,80000000,250000000,650000000],'uncertainty':[.5,.65,.85,1.0],'rationale':f'Day245 recovery: cash39.4m, support backlog115528 and enterprise billing suspension. Restore enterprise service through planB tier3, priced399 for retail so discounted planC tier2 remains the retail offer. Quote enterprise B contracts using researched budgets and quality. Preserve current retail C discounts and generous quotas. Fund ${sum(support.values())+5000:,.0f}/day support from the active book to clear aged issues in about3 days, rather than capping support against frozen collections. Maintain focused core development and no paid acquisition until retention and collections recover. Keep cash reserve and existing R&D projects.'}
(root/'policy.json').write_text(json.dumps(policy,indent=2))
print('RECOVERY_POLICY',json.dumps({'day':day,'support':sum(support.values())+5000,'development':sum(dev.values())+10000,'enterprise_prices':base}),flush=True)
exec(compile((root/'play_week.py').read_text(),'play_week.py','exec'),{'__name__':'__main__'})
"
  }
}

