{
  "/workspace/local/workspace/run-ceobench/operate.py": {
    "type": "add",
    "content": """"Weekly feedback control through public observations and the documented SDK."""
import json,re,math
from pathlib import Path
import novamind_api as nm
ROOT=Path('/workspace/local/workspace/run-ceobench')
def q(sql): return nm.query(sql)['rows']
def load(name,default):
    path=ROOT/name
    return json.loads(path.read_text()) if path.exists() else default
def save(name,value): (ROOT/name).write_text(json.dumps(value,indent=2))
for step in range(load('run_config.json',{'weeks':4})['weeks']):
    day=nm.vars.current_day
    cash=q('SELECT SUM(amount) AS x FROM ledger')[0]['x']
    if day>=500 or cash<=0: break
    previous=load(f'strategy_reports/week-{day-7:03}.json',{})['dashboard']
    quality={g:float(v) for g,v in re.findall(r'^((?:D_)?[SE]\d+)\s+(\d+\.\d+)',previous,re.M)}
    finance={r['category']:r['x'] for r in q(f'SELECT category,SUM(amount) AS x FROM ledger WHERE day>{day-7} GROUP BY category')}
    operating=sum(v for k,v in finance.items() if k not in ('initial_funding','market_research','group_research','research_project'))
    weekly_cost=-sum(v for k,v in finance.items() if v<0 and k not in ('market_research','group_research','research_project'))
    if cash<3000000 and operating<0:
        print('REVIEW_REQUIRED: cash reserve low; no mutation submitted.',flush=True);break
    book={r['group_id']:r for r in q("SELECT c.group_id,COUNT(*) AS n,SUM(s.seat_count) AS seats,SUM(s.effective_price*s.seat_count) AS mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id")}
    mrr=sum(r['mrr'] for r in book.values())
    pending=load('market_research_pending.json',{})
    markets=load('observed_market_control.json',{})
    known=q('SELECT group_id,info_level,last_research_day FROM group_info_levels WHERE info_level>0')
    for row in known:
        g=row['group_id']; asof=row['last_research_day'] or 0
        expected=pending.get(g,{}).get('expected_completion_day',100000)
        if expected<=day: asof=max(asof,expected)
        if g not in markets or asof>markets[g]['asof']:
            insight=nm.market.get_group_insights(g)
            drift=.03 if g=='E1' else .025 if g=='E2' else .02 if g.startswith(('S','D_S')) or g=='E3' else .015
            if g in markets and asof>markets[g]['asof']:
                old=markets[g]
                empirical=(insight['estimates']['quality_floor_q_min']-old['data']['estimates']['quality_floor_q_min'])/(asof-old['asof'])
                drift=max(.006,min(.07,.7*empirical+.3*old['drift']))
            markets[g]={'asof':asof,'drift':drift,'data':insight}
    save('observed_market_control.json',markets)
    floors={g:r['data']['estimates']['quality_floor_q_min']+r['drift']*max(0,day-r['asof']) for g,r in markets.items()}
    # Separate enterprise quality from the efficient retail service.
    tiers=[1,3,2]
    prices=[19,399,179]
    quotas=[250,700,1500]
    global_dev=10000 if day<450 else 5000
    old_config=q('SELECT * FROM config_history ORDER BY day DESC LIMIT 1')[0]
    old_promo=q("SELECT settings_json FROM config_overrides WHERE tool_name='set_promotion' ORDER BY id DESC LIMIT 1")
    old_promo=json.loads(old_promo[0]['settings_json']) if old_promo else {}
    promos={}; enterprise_prices={}; seller_prices={}; preferred={}; margins={}
    for g,r in markets.items():
        e=r['data']['estimates']; budget=e['willingness_to_pay']; units=e['usage_volume']
        if g.startswith(('S','D_S')):
            margin_c=max(0,quality[g]*1.25-floors[g])
            margin_b=max(0,quality[g]*1.5-floors[g])
            c=max(units*.002*30*1.3+4,budget*.9*margin_c/(margin_c+.4))
            old_c=max(0,old_config['price_C']-old_promo.get('by_group_plan',{}).get(g,{}).get('C',0))
            c=min(179,c,max(10,old_c)*1.10)
            b=max(budget*.9*margin_b/(margin_b+.4),c+units*.004*30*.6,min(700,units*1.5)*.006*30*1.15+4)
            b=min(399,b)
            promos[g]={'B':round(max(0,399-b),2),'C':round(max(0,179-c),2)}
            affordable_b=b<budget*1.2
            preferred[g]=.9 if affordable_b else .75
            margins[g]=margin_b if affordable_b else margin_c
        else:
            margin=max(0,quality[g]*1.5-floors[g])
            enterprise_prices[g]=round(max(units*.006*30*1.2+2,budget*.9*margin/(margin+.4)),2)
            seller_prices[g]=round(max(enterprise_prices[g],budget*.9),2)
            preferred[g]=.9;margins[g]=margin
    # Solve the documented log development curve for maintenance plus catch-up.
    global_gain=.0045*math.log1p(global_dev/5000)
    dev={}
    for g in quality:
        target=2.0 if not g.startswith(('S','D_S')) else 1.6
        catch=max(0,target-margins[g])/45
        required=max(0,(markets[g]['drift']+catch)/preferred[g]-global_gain)
        dev[g]=min(100000 if g in ('E1','S3') else 60000,round(5000*math.expm1(min(4,required/.0225))/500)*500)
    dev_budget=max(30000,min(mrr/30*.25,cash/60))
    if global_dev+sum(dev.values())>dev_budget:
        scale=max(0,(dev_budget-global_dev)/max(1,sum(dev.values())))
        dev={g:round(v*scale/500)*500 for g,v in dev.items()}
    if day>470: global_dev=0;dev={g:0 for g in dev}
    workload=q(f"SELECT group_id,SUM(CASE WHEN open_day>{day-7} THEN 1 ELSE 0 END) AS arrivals,SUM(CASE WHEN status='open' AND days_open>1 THEN 1 ELSE 0 END) AS aged FROM issues GROUP BY group_id")
    support={r['group_id']:max(100,math.ceil((r['arrivals']/7*1.15+r['aged']/3)/(.3 if r['group_id'].startswith(('S','D_S')) else .05)/100)*100) for r in workload}
    # Collections can be suspended: support is funded from book value and reserve.
    support_cap=max(20000,mrr/30*(.30 if sum(r['aged'] for r in workload)>10000 else .20))
    if sum(support.values())>support_cap:
        scale=support_cap/sum(support.values());support={g:round(v*scale/100)*100 for g,v in support.items()}
    if day>490: support={g:0 for g in support}
    peak=q(f'SELECT MAX(total_usage_units) AS x FROM service_day WHERE day>{day-7}')[0]['x']
    capacities=[50000,200000,800000,2500000,8000000,25000000,80000000,300000000]
    capacity=next((i for i,v in enumerate(capacities) if v>peak*1.35),7)
    if peak>250000000:
        population=sum(r['seats'] for r in book.values())
        quotas[2]=max(300,min(1000,int(260000000/max(1,population))))
    ads={}
    conversions={r['group_id']:r for r in q(f"SELECT c.group_id,COUNT(*) AS n,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) AS won FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.created_day>{day-7} AND c.customer_type='small' GROUP BY c.group_id")}
    paid={r['group_id']:r for r in q(f"SELECT c.group_id,COUNT(*) AS n,AVG(s.effective_price) AS price FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.created_day>{day-7} AND s.status='subscribed' AND c.acquisition_source IN ('social_media','search_ads','linkedin','content_marketing','referral_program') AND c.customer_type='small' GROUP BY c.group_id")}
    ad_history=q(f'SELECT group_id,channel_id,SUM(spend) AS spend,SUM(leads_generated) AS leads FROM ad_channel_leads WHERE day>{day-28} GROUP BY group_id,channel_id')
    if operating>0 and cash>10000000 and sum(r['aged'] for r in workload)<10000:
        for g,r in conversions.items():
            if r['won']/max(1,r['n'])<.3: continue
            choices=[a for a in ad_history if a['group_id']==g and a['spend']>=500]
            best=max(choices,key=lambda a:a['leads']/max(1,a['spend']))['channel_id'] if choices else 'referral_program'
            recent=q(f"SELECT SUM(spend) AS x FROM ad_channel_leads WHERE group_id='{g}' AND day>{day-7}")[0]['x'] or 0
            p=paid.get(g,{'n':0,'price':19})
            if recent/max(1,p['n'])>p['price']*(1.5 if day<350 else .8 if day<450 else .4): continue
            ads.setdefault(best,{})[g]=5000 if r['won']/max(1,r['n'])<.5 else 15000
    research=[];research_groups=[]
    tier_info=nm.research.list_research_projects()['tiers']
    reserve=weekly_cost*2+5000000
    research_budget=min(3000000,max(0,cash-reserve)*.15) if operating>0 and day<390 else 0
    for tier in (10,9,8,7,6,5,4,3,1,2):
        r=next(x for x in tier_info if x['tier']==tier)
        if not r['in_progress'] and r['cost']<=research_budget and r['mean_days']*1.7<500-day:
            research.append(tier);research_budget-=r['cost']
    if day==252: research_groups=['E2','E3','S1','S3']
    # Refresh the most valuable markets before drift estimates become stale.
    if day>280 and day<400 and cash>30000000:
        for g in ('E1','E2','E3','S1','S2','S3'):
            if day-markets[g]['asof']>60 and pending.get(g,{}).get('expected_completion_day',0)<=day:
                research_groups.append(g)
    oneoff=sum(next(x['cost'] for x in tier_info if x['tier']==t) for t in research)+700000*len(research_groups)
    weekly=max(0,operating)
    if weekly==0: weekly=max(100000,mrr*7/30-weekly_cost)
    points=[]
    for horizon in (7,28,84,182):
        n=min(horizon,500-day)/7
        growth=1.07 if day<350 else 1.015
        total=sum(min(max(25000000,mrr*7/30*.8),max(100000,weekly)*growth**w)*min(1,max(0,n-w)) for w in range(math.ceil(n)))
        points.append(round(max(0,cash-oneoff+total)))
    policy={'day':day,'prices':prices,'tiers':tiers,'quotas':quotas,'capacity':capacity,'ops':3000,'global_dev':global_dev,'dev_default':0,'dev':dev,'skip_core_override':True,'target_ops':support,'ads':ads,'ad_strength':{g:0 for g in quality},'promotion':{'by_group_plan':promos},'enterprise_plan':{g:'B' for g in enterprise_prices},'enterprise_prices':enterprise_prices,'renegotiation_prices':seller_prices,'retention_fraction':.95,'renegotiate':day%28==0,'research':research,'research_groups':research_groups,'forecasts':points,'uncertainty':[.4,.6,.8,.95],'rationale':f'Feedback review day{day}: cash${cash:,.0f}, MRR${mrr:,.0f}, operating cash flow${operating:,.0f}. Retain dedicated tier3 enterprise planB and efficient tier2 retail planC; offer retail B upgrades at prices covering compute. Price by researched budgets and quality surplus, forecast expectation drift from public research, and solve targeted development spend for maintenance plus45-day quality catch-up. Fund support from active book and clear aged issues, rather than frozen collections. Acquire only converting, profitable groups. Repeat affordable R&D to keep pace with competitors and refresh important market evidence.'}
    save('policy.json',policy)
    print('OPERATING_REVIEW',json.dumps({'day':day,'cash':cash,'mrr':mrr,'cash_flow':operating,'dev':global_dev+sum(dev.values()),'support':3000+sum(support.values()),'research':research,'market_research':research_groups,'ads':ads}),flush=True)
    exec(compile((ROOT/'play_week.py').read_text(),'play_week.py','exec'),{'__name__':'__main__'})
"
  },
