base={'E1':32,'E2':60,'E3':90,'D_E01':65,'D_E02':35,'D_E03':80,'D_E04':70,'D_E05':85,'D_E06':65,'D_E07':110,'D_E08':95,'D_E09':55,'D_E10':75}
base.update(policy.get('enterprise_prices',{}))
rows=qall("SELECT t.customer_id,t.sender,t.thread_type,t.offer_json,t.message_text,c.group_id FROM enterprise_turns t JOIN customers c USING(customer_id) WHERE t.message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY customer_id) AND t.closed=0 AND t.sender<>'agent' AND EXISTS (SELECT 1 FROM subscriptions s WHERE s.customer_id=t.customer_id AND s.status IN ('lead','subscribed')) ORDER BY t.message_id")
active={r['customer_id']:r for r in qall("SELECT s.customer_id,s.effective_price,s.plan FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND c.customer_type='large'")}
group_usage={r['group_id']:r['units'] for r in q(f"SELECT c.group_id,SUM(d.usage_units)*1.0/SUM(s.seat_count) AS units FROM daily_usage d JOIN customers c USING(customer_id) JOIN subscriptions s USING(customer_id) WHERE d.day>{day-7} AND s.status='subscribed' AND c.customer_type='large' GROUP BY c.group_id")}
customer_usage={r['customer_id']:r['units'] for r in qall(f"SELECT s.customer_id,SUM(d.usage_units)*1.0/SUM(s.seat_count) AS units FROM daily_usage d JOIN customers c USING(customer_id) JOIN subscriptions s USING(customer_id) WHERE d.day>{day-7} AND s.status='subscribed' AND c.customer_type='large' GROUP BY s.customer_id")}
unit_cost={1:.0003,2:.002,3:.006,4:.012,5:.03}
plan_tiers=dict(zip('ABC',policy.get('tiers',[1,2,3])))
deals=[]
seen=set()
for r in rows:
    cid=r['customer_id']
    if cid in seen: continue
    seen.add(cid)
    price=base.get(r['group_id'],60)
    plan=policy.get('enterprise_plan',{}).get(r['group_id'],'C')
    offer=json.loads(r['offer_json'] or '{}')
    counter=offer.get('price') if isinstance(offer,dict) else None
    if r['sender']=='customer':
        if counter is not None:
            match=re.search(r'Plan\s+([ABC])',r['message_text'])
            if match: plan=match.group(1)
            floor=group_usage.get(r['group_id'],100)*unit_cost[plan_tiers[plan]]*30*1.08+.5
            price=max(floor,float(counter)*1.02)
        elif r['thread_type'] in ('churn_prevention','renewal','plan_change') and cid in active:
            price=active[cid]['effective_price']*policy.get('retention_fraction',0.98)
        else: price*=0.7
    if r['thread_type']=='renegotiation' and cid in active:
        units=customer_usage.get(cid,group_usage.get(r['group_id'],100))
        old_profit=active[cid]['effective_price']-units*unit_cost[plan_tiers[active[cid]['plan']]]*30
        price=max(price,old_profit+units*unit_cost[plan_tiers[plan]]*30+1)
    deals.append([cid,[[plan,round(max(1,price),2)]]])
if deals:
    result=nm.enterprise.send_enterprise_deal(deals)
    failures=[r for r in result.get('results',[]) if not r.get('success')]
    print('ENTERPRISE',json.dumps({'sent':len(deals),'failures':failures}),flush=True)
    if failures: raise SystemExit('Deal failures require inspection; no week advanced.')

if policy.get('renegotiate'):
    occupied={r['customer_id'] for r in qall("SELECT DISTINCT customer_id FROM enterprise_turns t WHERE t.message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id) AND closed=0 AND (sender='agent' OR day>=%d)"%(day-7))}
    reneg=[]
    for r in qall("SELECT s.customer_id,s.effective_price,s.plan,c.group_id FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND c.customer_type='large'"):
        desired=policy.get('renegotiation_prices',{}).get(r['group_id'],base.get(r['group_id'],60))
        plan=policy.get('enterprise_plan',{}).get(r['group_id'],'C')
        units=customer_usage.get(r['customer_id'],group_usage.get(r['group_id'],100))
        old_profit=r['effective_price']-units*unit_cost[plan_tiers[r['plan']]]*30
        new_profit=desired-units*unit_cost[plan_tiers[plan]]*30
        if policy.get('profit_menu'):
            cost_b=units*unit_cost[plan_tiers['B']]*30
            cost_c=units*unit_cost[plan_tiers['C']]*30
            target_profit=max(old_profit+max(2,(units*unit_cost[plan_tiers[r['plan']]]*30-min(cost_b,cost_c))*.5),desired-cost_b)
            if r['customer_id'] not in occupied:
                reneg.append([r['customer_id'],[['C',round(max(1,cost_c+target_profit),2)],['B',round(max(1,cost_b+target_profit),2)]]])
        elif r['customer_id'] not in occupied and new_profit>max(old_profit*1.1,old_profit+1):
            reneg.append([r['customer_id'],[[plan,desired]]])
    if reneg:
        result=nm.enterprise.send_enterprise_deal(reneg)
        print('RENEGOTIATE',json.dumps({'sent':len(reneg),'failures':[r for r in result.get('results',[]) if not r.get('success')]}),flush=True)

cash=q('SELECT SUM(amount) AS cash FROM ledger')[0]['cash']
points=policy['forecasts']
widths=policy.get('uncertainty',[0.22,0.45,0.65,0.75])
pred={k:{'point':v,'lower':max(0,v*(1-w)),'upper':v*(1+w)} for k,v,w in zip(['cash_1wk','cash_4wk','cash_12wk','cash_26wk'],points,widths)}
rationale=policy['rationale']+f' Observed day {day}, cash ${cash:,.0f}; handled {len(deals)} actionable enterprise negotiations. Watching collections, customer retention, capacity and marginal acquisition returns.'
print('ADVANCING',json.dumps({'day':day,'forecasts':pred,'rationale':rationale}),flush=True)
result=next_week(predictions=pred,rationale=rationale,request_id=f'policy-week-{day:03d}')
(root/'strategy_reports').mkdir(exist_ok=True)
(root/'strategy_reports'/f'week-{day:03d}.json').write_text(json.dumps(result,indent=2))
pending_path=root/'market_research_pending.json'
cache_path=root/'enterprise_research.json'
if pending_path.exists() and cache_path.exists():
    pending=json.loads(pending_path.read_text())
    cache=json.loads(cache_path.read_text())
    for g,entry in pending.items():
        if result.get('day',0)>=entry.get('expected_completion_day',10000) and not entry.get('cache_invalidated'):
            cache.pop(g,None)
            entry['cache_invalidated']=True
    cache_path.write_text(json.dumps(cache,indent=2))
    pending_path.write_text(json.dumps(pending,indent=2))
dashboard=result.get('dashboard','')
print('WEEK_RESULT','\n'.join(dashboard.splitlines()[:23]),flush=True)

