"""Run exactly one observed, managed week using only the documented SDK."""
import json, math, re
from pathlib import Path
import novamind_api as nm
from novamind_api._client import next_week

root=Path('/workspace/local/workspace/run-ceobench')
policy=json.loads((root/'policy.json').read_text())
day=nm.vars.current_day
if day>=500:
    raise SystemExit('Already at horizon; no advance submitted.')
if day!=policy['day']:
    raise SystemExit(f"Policy day {policy['day']} differs from current day {day}; no actions submitted.")
review_path=root/'review_before_day.json'
if review_path.exists() and day>=json.loads(review_path.read_text())['day']:
    raise SystemExit(f'Completed prior week; review requested before day{day} actions. No new mutation submitted.')
core_cache_path=root/'enterprise_research.json'
if core_cache_path.exists() and 224<=day<400 and not policy.get('skip_core_override'):
    core_cash=nm.query('SELECT SUM(amount) AS cash FROM ledger')['rows'][0]['cash']
    if core_cash>5000000:
        cache=json.loads(core_cache_path.read_text())
        previous_path=root/'strategy_reports'/f'week-{day-7:03d}.json'
        if previous_path.exists():
            previous=json.loads(previous_path.read_text())['dashboard']
            qualities={g:float(v) for g,v in re.findall(r'^((?:D_)?[SE]\d+)\s+(\d+\.\d+)',previous,re.M)}
            multipliers={1:.6,2:.75,3:.9,4:1.,5:1.1}
            investment={}
            for g in ('E1','E2','E3'):
                if g not in cache: continue
                plan=policy.get('enterprise_plan',{}).get(g,'C')
                tier=dict(zip('ABC',policy.get('tiers',[1,2,3])))[plan]
                floor=cache[g]['estimates']['quality_floor_q_min']+.006*max(0,day-cache[g].get('_read_day',day))
                gap=qualities[g]*multipliers[tier]/.6-floor
                amount=50000 if gap<1.5 else 20000 if gap<2.3 else 5000
                policy.setdefault('dev',{})[g]=amount
                investment[g]={'quality_headroom':round(gap,3),'daily_development':amount}
            if investment:
                print('CORE_QUALITY_INVESTMENT',json.dumps(investment),flush=True)
                policy['rationale']+=' Accelerate development in core enterprise groups with less than2.3 quality headroom, then taper spending as price capacity improves.'
                (root/'policy.json').write_text(json.dumps(policy,indent=2))
def q(sql): return nm.query(sql)['rows']
def qall(sql):
    rows=[]
    offset=0
    while True:
        batch=q(sql+f' LIMIT 4000 OFFSET {offset}')
        rows.extend(batch)
        if len(batch)<4000: return rows
        offset+=4000
def action(label,fn,*args,**kwargs):
    cache_labels={'PRICES','TIERS','QUOTAS','CAPACITY','SPEND','TARGET_DEV','ACQUISITION','AD_MONETIZATION','PROMOTION','LEAD_PROMOTION','TARGET_OPS'}
    settings_path=root/'known_applied_settings.json'
    signature=json.dumps({'args':args,'kwargs':kwargs},sort_keys=True)
    settings=json.loads(settings_path.read_text()) if settings_path.exists() else {}
    if label in cache_labels and settings.get(label)==signature:
        print(label,'unchanged',flush=True)
        return {'unchanged':True}
    result=fn(*args,**kwargs)
    if label in cache_labels:
        settings[label]=signature
        settings_path.write_text(json.dumps(settings,indent=2))
    detail=result if label in ('RESEARCH','GROUP_RESEARCH','DISCOVERY','SOCIAL') else {'ok':True,'total_extra_per_day':result.get('total_extra_per_day'),'total_per_day':result.get('total_per_day')}
    print(label,json.dumps(detail),flush=True)
    return result

# Smooth scheduled billing variation in the cash-flow baseline.
flow_path=root/'forecast_cashflow_history.json'
if flow_path.exists():
    flows=json.loads(flow_path.read_text())
    recent_flows=[v for k,v in sorted(flows.items(),key=lambda x:int(x[0])) if int(k)<=day][-4:]
    if len(recent_flows)==4:
        delta=.75*(sum(recent_flows)/4-recent_flows[-1])
        prior_points=policy['forecasts'][:]
        policy['forecasts']=[round(max(0,v+delta*min(h,500-day)/7)) for v,h in zip(prior_points,(7,28,84,182))]
        policy['uncertainty']=[(w*v+abs(delta*min(h,500-day)/7)*(.12+.02*min(h,500-day)/7))/max(1,n) for w,v,n,h in zip(policy['uncertainty'],prior_points,policy['forecasts'],(7,28,84,182))]
        policy['rationale']+=' Cash forecasts blend the latest weekly flow with the trailing month to smooth scheduled billing variation.'
        (root/'policy.json').write_text(json.dumps(policy,indent=2))

# Buy the same planned quality gain from the least expensive mix of global
# and targeted development, using the two documented log curves.
if 'dev' in policy and 'global_dev' in policy:
    old_global=policy['global_dev'];old_targets=policy['dev']
    old_total=old_global+sum(old_targets.values())
    planned_gain={g:.0045*math.log1p(old_global/5000)+.0225*math.log1p(v/5000) for g,v in old_targets.items()}
    best=(old_total,old_global,old_targets)
    for candidate in sorted(set([old_global]+[v for v in (0,5000,10000,20000,30000,50000,75000,100000,150000,200000,300000,500000) if v>=old_global])):
        shared=.0045*math.log1p(candidate/5000)
        targets={g:max(0,math.ceil(5000*math.expm1(max(0,(gain-shared)/.0225))/500-1e-9)*500) for g,gain in planned_gain.items()}
        total=candidate+sum(targets.values())
        if total<best[0]: best=(total,candidate,targets)
    if best[0]<old_total:
        policy['global_dev']=best[1];policy['dev']=best[2]
        savings=old_total-best[0]
        old_points=policy['forecasts'][:]
        policy['forecasts']=[round(v+savings*min(h,500-day)) for v,h in zip(old_points,(7,28,84,182))]
        policy['uncertainty']=[w*v/max(1,n) for w,v,n in zip(policy['uncertainty'],old_points,policy['forecasts'])]
        policy['rationale']=re.sub(r'Daily development \$[\d,]+',f'Daily development ${best[0]:,.0f}',policy['rationale'])
        policy['rationale']+=f' Final development uses global ${best[1]:,.0f}/day and targeted ${sum(best[2].values()):,.0f}/day, preserving every group planned daily quality gain.'
        (root/'policy.json').write_text(json.dumps(policy,indent=2))
        print('DEVELOPMENT_ALLOCATION',json.dumps({'global':best[1],'targeted':sum(best[2].values()),'saved_daily':savings}),flush=True)

cash=q('SELECT SUM(amount) AS cash FROM ledger')[0]['cash']
book=q("SELECT c.group_id,COUNT(*) AS accounts,SUM(s.seat_count) AS seats,SUM(s.effective_price*s.seat_count) AS mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id")
print('BEFORE',json.dumps({'day':day,'cash':cash,'groups_with_subscribers':len(book),'mrr':sum(r['mrr'] for r in book)}),flush=True)
known=q('SELECT group_id,discovered_day FROM group_info_levels WHERE info_level>0')
groups=[r['group_id'] for r in known]
if policy.get('discover',0):
    for _ in range(policy['discover']):
        if len(groups)>=26: break
        result=action('DISCOVERY',nm.market.research_market)
        g=result.get('discovered_group_id')
        if g:
            groups.append(g)
            insight=action('NEW_INSIGHT',nm.market.get_group_insights,g)

if 'prices' in policy: action('PRICES',nm.pricing.set_prices,**dict(zip('ABC',policy['prices'])))
if 'tiers' in policy: action('TIERS',nm.pricing.set_model_tiers,**dict(zip('ABC',policy['tiers'])))
if 'quotas' in policy: action('QUOTAS',nm.pricing.set_usage_quotas,**dict(zip('ABC',policy['quotas'])))
if 'capacity' in policy: action('CAPACITY',nm.infrastructure.set_capacity_tier,policy['capacity'])
if 'ops' in policy: action('SPEND',nm.marketing.set_daily_spend,operations=policy['ops'],development=policy['global_dev'])
if 'dev_default' in policy:
    dev={g:policy.get('dev',{}).get(g,policy['dev_default']) for g in groups}
    action('TARGET_DEV',nm.analytics.set_targeted_dev_spend,dev)
if 'ads' in policy: action('ACQUISITION',nm.marketing.set_targeted_ad_spend,policy['ads'])
if 'ad_strength' in policy: action('AD_MONETIZATION',nm.marketing.set_ads_strength,by_group=policy['ad_strength'])
if 'promotion' in policy: action('PROMOTION',nm.pricing.set_promotion,**policy['promotion'])
if 'lead_promotion' in policy: action('LEAD_PROMOTION',nm.marketing.set_lead_promotion,**policy['lead_promotion'])
