import json
from pathlib import Path
import novamind_api as nm

day=nm.vars.current_day
cohort="SELECT DISTINCT customer_id FROM enterprise_turns WHERE day=441 AND sender='agent' AND instr(offer_json,'\"C\"')>0"
queries={
 'optional_offer_cohort': f"SELECT c.group_id,COALESCE(s.plan,'inactive') AS current_plan,COUNT(*) AS accounts,SUM(s.seat_count) AS seats,SUM(s.effective_price*s.seat_count) AS mrr FROM ({cohort}) x JOIN customers c USING(customer_id) LEFT JOIN subscriptions s ON s.customer_id=x.customer_id AND s.status='subscribed' GROUP BY c.group_id,COALESCE(s.plan,'inactive')",
 'enterprise_C': "SELECT c.group_id,COUNT(*) AS accounts,SUM(s.seat_count) AS seats,SUM(s.effective_price*s.seat_count) AS mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='large' AND s.status='subscribed' AND s.plan='C' GROUP BY c.group_id",
 'remaining_B': "SELECT c.group_id,COUNT(*) AS accounts,SUM(s.seat_count) AS seats,SUM(s.effective_price*s.seat_count) AS mrr,SUM(CASE WHEN s.effective_price<27 THEN s.seat_count ELSE 0 END) AS seats_below_27,SUM(CASE WHEN s.effective_price<27 THEN (27-s.effective_price)*s.seat_count ELSE 0 END) AS maximum_monthly_loss_at_27_cost FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='large' AND s.status='subscribed' AND s.plan='B' GROUP BY c.group_id",
 'enterprise_usage': f"SELECT c.group_id,s.plan,SUM(d.usage_units)*1.0/SUM(s.seat_count) AS mean_daily_units,SUM(d.usage_units) AS units FROM daily_usage d JOIN subscriptions s USING(customer_id) JOIN customers c USING(customer_id) WHERE c.customer_type='large' AND s.status='subscribed' AND d.day>{day-7} GROUP BY c.group_id,s.plan",
 'cohort_latest_messages': f"SELECT c.group_id,t.sender,t.thread_type,t.message_text,t.offer_json,t.closed,t.close_reason FROM enterprise_turns t JOIN customers c USING(customer_id) WHERE t.customer_id IN ({cohort}) AND t.message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY customer_id) ORDER BY t.message_id DESC LIMIT 12",
}
result={'day':day}
for name,sql in queries.items():
 result[name]=nm.query(sql)['rows']
 print(name,json.dumps(result[name]),flush=True)
Path(f'enterprise_C_public_{day}.json').write_text(json.dumps(result,indent=2))
"
  }
}

