    "content": """"Estimate active-book contribution from documented subscriptions and usage."""
import json
from pathlib import Path
import novamind_api as nm

day=nm.vars.current_day
q=lambda sql:nm.query(sql)['rows']
config=q('SELECT * FROM config_history ORDER BY day DESC LIMIT 1')[0]
book=q("SELECT c.group_id,s.plan,COUNT(*) AS accounts,SUM(s.seat_count) AS seats,SUM(s.effective_price*s.seat_count) AS mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id,s.plan")
usage={(r['group_id'],r['plan']):r['units'] for r in q(f"SELECT c.group_id,s.plan,SUM(d.usage_units)*1.0/SUM(s.seat_count) AS units FROM daily_usage d JOIN subscriptions s USING(customer_id) JOIN customers c USING(customer_id) WHERE d.day>{day-7} AND s.status='subscribed' GROUP BY c.group_id,s.plan")}
cost={1:.0003,2:.002,3:.006,4:.012,5:.03}
groups={}
for row in book:
 g=row['group_id'];p=row['plan']
 units=min(config['quota_'+p],usage.get((g,p),config['quota_'+p])*1.1)
 compute=row['seats']*units*cost[config['tier_'+p]]*30
 r=groups.setdefault(g,{'mrr':0,'estimated_monthly_compute':0,'plans':[]})
 r['mrr']+=row['mrr'];r['estimated_monthly_compute']+=compute
 r['plans'].append({**row,'estimated_monthly_compute':compute,'mean_daily_units':usage.get((g,p))})
for g,r in groups.items():
 r['contribution']=r['mrr']-r['estimated_monthly_compute']
 print(g,json.dumps({k:v for k,v in r.items() if k!='plans'}),flush=True)
Path(f'profitability_public_{day}.json').write_text(json.dumps({'day':day,'groups':groups},indent=2))
"
  }
}

